using UnityEngine;
using Flynn.Events;

/// <summary>
/// Player startup script. Owns the player's wiring to the <see cref="ResourceManager"/>:
/// it subscribes to resource events on startup and is the publisher that raises player hits
/// via <see cref="EmitHit"/>. Also supports the new <see cref="ToolHitContext"/>-based
/// hit flow that routes through <see cref="ResourceNode.TryApplyToolHit"/> with tool
/// effectiveness lookups.
/// </summary>
public class PlayerInitializer : MonoBehaviour
{
    [Header("Debug")]
    [Tooltip("Press to raise a test hit at the player's position (verifies the event pipe). None = disabled.")]
    [SerializeField] private KeyCode _debugHitKey = KeyCode.None;

    private void OnEnable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit += HandleResourceHit;
    }

    private void OnDisable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit -= HandleResourceHit;
    }

    private void Update()
    {
        if (_debugHitKey != KeyCode.None && Input.GetKeyDown(_debugHitKey))
            EmitHit(transform.position, null, 1);
    }

    /// <summary>Publisher: raise a player hit through the manager (legacy PlayerHitInfo path).</summary>
    public void EmitHit(Vector3 point, GameObject target = null, int power = 1)
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.RaiseHit(new PlayerHitInfo(point, target, power));
    }

    /// <summary>
    /// Publisher: raise a tool hit with full context. Routes through the effectiveness
    /// system by finding the <see cref="ResourceNode"/> on the target and calling
    /// <see cref="ResourceNode.TryApplyToolHit"/>. Also publishes <see cref="ToolHitTarget"/>
    /// on the GameEventBus for feedback/audio.
    /// </summary>
    public void EmitToolHit(ToolHitContext hit)
    {
        // Publish tool hit event for feedback/audio
        PublishEvent(new ToolHitTarget(hit));

        // Find and apply to resource nodes
        if (hit.Source == null) return;
        ResourceNode node = hit.Source.GetComponentInParent<ResourceNode>();
        if (node == null && ResourceManager.Instance != null)
        {
            // Legacy: try to find a ResourceNode on the hit target
            // (the hit.Source is the player, not the target — need different resolution)
        }

        // Also raise through the legacy ResourceManager path for backward compat
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.RaiseHit(new PlayerHitInfo(hit.HitPoint, hit.Source, hit.Damage));
    }

    /// <summary>Player-side reaction to resource events. Empty hook for now.</summary>
    private void HandleResourceHit(PlayerHitInfo info) { }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;

/// <summary>
/// Single-responsibility component that owns all mouse → world target detection. Every interaction
/// reads what's under the cursor from here; nothing keeps its own proximity registry.
///
/// It no longer casts its own rays: <see cref="MousePointer"/> does ONE cursor raycast per frame
/// (against its combined world mask) and this component derives every hovered target from that one
/// shared hit. The object under the cursor is resolved once; each concern asks it for the component
/// it cares about and applies its own range gate. Consequence of the single union cast: the closest
/// object under the cursor wins across all layers (uniform occlusion) — there are no per-concern
/// masks that can see a target through something in front of it.
///
/// Other systems read the public properties; this component only ever reads — it writes nothing.
/// Requires a <see cref="MousePointer"/> in the scene whose mask covers ground + resources + pickups
/// + grapple + melee surfaces (the union of what used to be per-concern masks here).
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class PlayerMouseAimer : MonoBehaviour
{
    [SerializeField] private float _maxAimDistance = 30f;

    /// <summary>Max distance from the player to a resource or pickup for it to count as interactable.</summary>
    [SerializeField] private float _interactionRange = 3f;

    /// <summary>Public access to the interaction range for other controllers.</summary>
    public float InteractionRange => _interactionRange;

    [Tooltip("Max distance from the player to a melee surface for a wrench swing to register its tool/hit.")]
    [SerializeField] private float _meleeRange = 2.5f;

    private MousePointer _pointer;

    // ── Public properties ─────────────────────────────────────────────────────

    /// <summary>World-space position the mouse cursor is pointing at.</summary>
    public Vector3 WorldAimPoint { get; private set; }

    /// <summary>
    /// The ResourceNode the mouse ray is pointing at, or null.
    /// Only set when the hit node is within <see cref="_interactionRange"/> of the player.
    /// </summary>
    public ResourceNode HoveredResource { get; private set; }

    /// <summary>
    /// The WorldItemPickup the mouse ray is pointing at, or null. (Legacy; new world objects use
    /// <see cref="WorldItem"/> / <see cref="HoveredKeyPickup"/>.) Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItemPickup HoveredPickup { get; private set; }

    /// <summary>
    /// The non-auto-collect <see cref="WorldItem"/> under the cursor (e.g. the wrench), or null.
    /// These require the pickup key — auto-collecting items magnet themselves and never appear here.
    /// Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItem HoveredKeyPickup { get; private set; }

    /// <summary>The RopeAnchor the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopeAnchor HoveredAnchor { get; private set; }

    /// <summary>The RopePullable the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopePullable HoveredPullable { get; private set; }

    /// <summary>Exact world surface point hit on the current grapple target. Valid only when an anchor or pullable is hovered.</summary>
    public Vector3 HoveredGrapplePoint { get; private set; }

    /// <summary>
    /// Animator AttackIndex of the surface under the cursor within <see cref="_meleeRange"/>.
    /// Defaults to 4 (wrench / "air") when nothing meleeable is in reach. The wrench swing
    /// reads this to decide which tool to transform into.
    /// </summary>
    public int SwingAnimIndex { get; private set; } = 4;

    /// <summary>
    /// The ResourceNode under the cursor within melee reach, or null. Used by the swing to
    /// apply harvest damage. Non-resource surfaces (HittableSurface) drive the tool anim but
    /// leave this null (no damage).
    /// </summary>
    public ResourceNode MeleeResource { get; private set; }

    /// <summary>
    /// The interaction-prompt provider the player is currently targeting (pickup, grapple point,
    /// NPC, …), or null. Generic — the HUD reads this and renders whatever prompt it returns.
    /// </summary>
    public IInteractionPromptProvider HoveredInteractable { get; private set; }

    /// <summary>The GameObject the mouse ray is pointing at (from MousePointer), or null.</summary>
    public GameObject HoveredGameObject
    {
        get
        {
            if (_pointer == null) _pointer = MousePointer.Instance;
            return _pointer != null ? _pointer.HoverObject : null;
        }
    }

    /// <summary>
    /// Unified hover result produced each frame. All consumers should read from this
    /// instead of the individual HoveredXxx properties (which are deprecated).
    /// </summary>
    public PlayerAimHoverResult HoverResult { get; private set; }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Update()
    {
        if (_pointer == null) _pointer = MousePointer.Instance;
        if (_pointer == null) return;

        GameObject hovered = _pointer.HoverObject;
        bool hasHit = _pointer.HasHit;
        Vector3 point = _pointer.WorldPoint;

        UpdateAimPoint(hasHit, point);
        UpdateHoveredResource(hovered);
        UpdateHoveredPickup(hovered);
        UpdateHoveredKeyPickup(hovered);
        UpdateHoveredGrapple(hovered, point);
        UpdateHoveredGrabbable(hovered);
        UpdateMeleeTarget(hovered, hasHit, point);
        UpdateHoveredInteractable(hovered, hasHit, point);

        // Build unified hover result
        BuildHoverResult(hasHit, point, hovered);
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void UpdateAimPoint(bool hasHit, Vector3 point)
    {
        if (hasHit)
        {
            WorldAimPoint = point;
            return;
        }
        // Miss: intersect the horizontal plane at this object's Y so aim still resolves over open ground.
        var plane = new Plane(Vector3.up, new Vector3(0f, transform.position.y, 0f));
        if (plane.Raycast(_pointer.WorldRay, out float dist))
            WorldAimPoint = _pointer.WorldRay.GetPoint(Mathf.Min(dist, _maxAimDistance));
    }

    private void UpdateHoveredResource(GameObject hovered)
    {
        ResourceNode node = Find<ResourceNode>(hovered);
        HoveredResource = node != null && WithinInteractionRange(node.transform.position) ? node : null;
    }

    private void UpdateHoveredPickup(GameObject hovered)
    {
        WorldItemPickup pickup = Find<WorldItemPickup>(hovered);
        HoveredPickup = pickup != null && WithinInteractionRange(pickup.transform.position) ? pickup : null;
    }

    private void UpdateHoveredKeyPickup(GameObject hovered)
    {
        WorldItem item = Find<WorldItem>(hovered);
        // Only key-pickup items (e.g. the wrench) surface here; auto-collect items magnet themselves.
        bool needsKey = item != null && item.Item != null && !item.Item.AutoCollects;
        HoveredKeyPickup = needsKey && WithinInteractionRange(item.transform.position) ? item : null;
    }

    private void UpdateHoveredGrapple(GameObject hovered, Vector3 point)
    {
        // Whichever marker the hovered object carries decides the kind; range is left to the
        // controller (RopeLassoConfig owns it). Anchor and pullable are mutually exclusive.
        RopeAnchor anchor = Find<RopeAnchor>(hovered);
        if (anchor != null)
        {
            HoveredAnchor = anchor;
            HoveredPullable = null;
            HoveredGrapplePoint = point;
            return;
        }

        RopePullable pullable = Find<RopePullable>(hovered);
        HoveredAnchor = null;
        HoveredPullable = pullable;
        if (pullable != null) HoveredGrapplePoint = point;
    }

    private void UpdateMeleeTarget(GameObject hovered, bool hasHit, Vector3 point)
    {
        // ResourceNode wins (it carries damage + its own tool); otherwise a HittableSurface decides
        // the tool; nothing in reach = wrench (air).
        MeleeResource = null;
        SwingAnimIndex = 4;
        if (!hasHit || hovered == null) return;
        if (Vector3.Distance(transform.position, point) > _meleeRange) return;

        ResourceNode node = Find<ResourceNode>(hovered);
        if (node != null)
        {
            MeleeResource = node;
            SwingAnimIndex = node.AttackAnimIndex;
            return;
        }

        HittableSurface surface = Find<HittableSurface>(hovered);
        if (surface != null)
            SwingAnimIndex = surface.AttackAnimIndex;
    }

    private void UpdateHoveredInteractable(GameObject hovered, bool hasHit, Vector3 point)
    {
        HoveredInteractable = null;

        // 1) Generic interaction target within reach — pickups, NPCs, inspectables, etc.
        if (hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange)
        {
            var provider = hovered.GetComponentInParent<IInteractionPromptProvider>();
            if (provider != null) { HoveredInteractable = provider; return; }
        }

        // 2) Fall back to the rope-lasso targets (their reach is owned by the lasso controller,
        //    so they prompt even past the generic interaction range).
        if (HoveredAnchor is IInteractionPromptProvider anchor)        HoveredInteractable = anchor;
        else if (HoveredPullable is IInteractionPromptProvider pull)   HoveredInteractable = pull;
    }

    private void UpdateHoveredGrabbable(GameObject hovered)
    {
        HoveredGrabbable = null;
        if (hovered == null) return;

        Grabbable g = hovered.GetComponentInParent<Grabbable>();
        if (g == null) return;

        // Range gate: must be within interaction range (or already held)
        if (g.IsHeld || Vector3.Distance(transform.position, g.transform.position) <= _interactionRange)
            HoveredGrabbable = g;
    }

    /// <summary>The Grabbable object the mouse ray is pointing at, or null.</summary>
    public Grabbable HoveredGrabbable { get; private set; }

    /// <summary>Component of type T on the hovered object or its parents, or null.</summary>
    private static T Find<T>(GameObject hovered) where T : Component
        => hovered != null ? hovered.GetComponentInParent<T>() : null;

    private bool WithinInteractionRange(Vector3 worldPos)
        => Vector3.Distance(transform.position, worldPos) <= _interactionRange;

    private void BuildHoverResult(bool hasHit, Vector3 point, GameObject hovered)
    {
        HoverResult = new PlayerAimHoverResult
        {
            HasTarget = hasHit || HoveredAnchor != null || HoveredPullable != null || HoveredGrabbable != null,
            WorldPoint = WorldAimPoint,
            WorldItem = HoveredKeyPickup,
            ResourceNode = HoveredResource,
            MeleeResource = MeleeResource,
            RopeAnchor = HoveredAnchor,
            RopePullable = HoveredPullable,
            ScanTarget = hovered != null ? Find<ScanTarget>(hovered) : null,
            Interactable = HoveredInteractable,
            Grabbable = HoveredGrabbable,
            GrapplePoint = HoveredGrapplePoint,
            InInteractionRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange,
            InMeleeRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _meleeRange,
            SwingAnimIndex = SwingAnimIndex,
        };
    }
}

using UnityEngine;

/// <summary>
/// Applies a momentum lean to a billboarded 2D sprite visual by adding X/Z euler
/// rotation after the Billboard component sets the camera-facing rotation.
/// Y rotation is never touched — Billboard owns that. Runs after Billboard via
/// DefaultExecutionOrder. Position is offset so the lean pivots from the feet.
/// </summary>
[DefaultExecutionOrder(100)]
public class VelocityLeanDriver : MonoBehaviour
{
    [SerializeField] private SolarpunkCharacterController _controller;
    [SerializeField] private float _maxLeanDeg = 12f;
    [SerializeField] private float _leanSpeed = 8f;
    [Tooltip("Vertical distance from transform origin down to feet for pivot offset.")]
    [SerializeField] private float _footOffsetY = 0.455f;

    private float _currentLeanX;
    private float _currentLeanZ;
    private float _targetLeanX;
    private float _targetLeanZ;
    private Vector3 _baseLocalPos;

    private void Awake()
    {
        _baseLocalPos = transform.localPosition;
    }

    private void LateUpdate()
    {
        if (_controller == null) return;

        // Use MoveInput direction + NormalizedSpeed so lean is responsive
        // even when Rigidbody velocity gets zeroed by the controller between frames
        var input = _controller.MoveInput;
        var speed = _controller.NormalizedSpeed; // 0-1

        if (speed > 0.05f && input.sqrMagnitude > 0.001f)
        {
            // Normalize the XZ input for direction
            var dir = new Vector3(input.x, 0f, input.z).normalized;
            // Moving +Z → lean forward (positive X rotation)
            // Moving +X → lean right (negative Z rotation)
            _targetLeanX = dir.z * speed * _maxLeanDeg;
            _targetLeanZ = -dir.x * speed * _maxLeanDeg;
        }
        else
        {
            _targetLeanX = 0f;
            _targetLeanZ = 0f;
        }

        _currentLeanX = Mathf.Lerp(_currentLeanX, _targetLeanX, _leanSpeed * Time.deltaTime);
        _currentLeanZ = Mathf.Lerp(_currentLeanZ, _targetLeanZ, _leanSpeed * Time.deltaTime);

        // Add lean to Billboard's rotation (X and Z only, Y preserved)
        var euler = transform.eulerAngles;
        euler.x += _currentLeanX;
        euler.z += _currentLeanZ;
        transform.eulerAngles = euler;

        // Offset position so lean pivots from feet instead of center
        var leanRot = Quaternion.Euler(_currentLeanX, 0f, _currentLeanZ);
        Vector3 feetOffset = new Vector3(0f, -_footOffsetY, 0f);
        transform.localPosition = _baseLocalPos + leanRot * feetOffset - feetOffset;
    }
}

using UnityEngine;

/// <summary>
/// Add to any world GameObject that needs dynamic depth-based sorting.
///
/// LateUpdate computes a sorting order from the object's depth along the
/// configured sort axis and stamps it onto all tracked SpriteRenderers.
///
/// Design intent
/// ─────────────
/// • One SortableSprite per logical object root (tree root, character root).
/// • Multiple SpriteRenderers on a single object (e.g. shadow + trunk + canopy)
///   are all set to the same order — they share a depth bucket.
/// • Use _relativeOrders[] offsets if layers within one object must be stacked
///   (e.g. shadow = base−1, trunk = base, canopy = base+1).
///
/// Foot-position sorting
/// ─────────────────────
/// Set _sortOriginOffset to the foot of the object (bottom of its bounding box)
/// for correct results when tall objects stand close together.
/// For a tree prefab with pivot at ground level this is Vector3.zero (default).
/// For a character with pivot at origin: Vector3.zero is already correct.
/// </summary>
public class SortableSprite : MonoBehaviour
{
    [SerializeField] private SpriteSortingConfigSO _config;

    [Tooltip("Rendered sprites to receive the computed sorting order.\n" +
             "Leave empty to auto-collect all SpriteRenderers in children on Awake.")]
    [SerializeField] private SpriteRenderer[] _renderers;

    [Tooltip("Per-renderer sorting-order offsets relative to the computed base.\n" +
             "Must match length of _renderers (or be empty for zero offsets).")]
    [SerializeField] private int[] _relativeOrders;

    [Tooltip("Local offset from this transform used as the depth-sample origin.\n" +
             "For ground-pivot objects: leave at (0,0,0).\n" +
             "For centre-pivot characters: try (0, -halfHeight, 0) to sample the feet.")]
    [SerializeField] private Vector3 _sortOriginOffset = Vector3.zero;

    // ── Lifecycle ─────────────────────────────────────────────────────────────

    private void Awake()
    {
        if (_renderers == null || _renderers.Length == 0)
            _renderers = GetComponentsInChildren<SpriteRenderer>(includeInactive: true);
    }

    /// <summary>
    /// Computes the current base sorting order for this object's depth position.
    /// Callers can add their own per-renderer offsets on top of this.
    /// </summary>
    public int ComputeBaseOrder()
    {
        if (_config == null) return 0;
        Vector3 sortPos = transform.position + transform.TransformDirection(_sortOriginOffset);
        float depth = Vector3.Dot(sortPos, _config.SortAxisNormalized);
        return _config.baseOrder - Mathf.RoundToInt(depth * _config.stepsPerUnit);
    }

    private void LateUpdate()
    {
        if (_config == null || _renderers == null) return;

        int baseOrder = ComputeBaseOrder();

        for (int i = 0; i < _renderers.Length; i++)
        {
            if (_renderers[i] == null) continue;
            int offset = (_relativeOrders != null && i < _relativeOrders.Length)
                ? _relativeOrders[i]
                : 0;
            _renderers[i].sortingOrder = baseOrder + offset;
        }
    }

    // ── Editor helpers ────────────────────────────────────────────────────────

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        if (_config == null) return;

        // Show the sort-origin point
        Vector3 sortPos = transform.position + transform.TransformDirection(_sortOriginOffset);
        Gizmos.color = new Color(1f, 0.8f, 0.1f, 0.9f);
        Gizmos.DrawWireSphere(sortPos, 0.08f);

        // Show depth arrow along sort axis
        Vector3 axis = _config.SortAxisNormalized;
        Gizmos.color = new Color(1f, 0.8f, 0.1f, 0.5f);
        Gizmos.DrawRay(sortPos, axis * 1.5f);

        // Live order label via Handles
#if UNITY_EDITOR
        Vector3 sortPosWS = transform.position + transform.TransformDirection(_sortOriginOffset);
        float depth = Vector3.Dot(sortPosWS, axis);
        int order = _config.baseOrder - Mathf.RoundToInt(depth * _config.stepsPerUnit);
        UnityEditor.Handles.Label(
            sortPos + Vector3.up * 0.3f,
            $"order: {order}",
            new GUIStyle { normal = { textColor = new Color(1f, 0.9f, 0.2f) }, fontSize = 10 });
#endif
    }
#endif
}

using UnityEngine;

/// <summary>
/// Shared configuration for the 2.5D sprite depth-sorting system.
/// Assign one asset to both SpriteSortingManager (camera setup) and every
/// SortableSprite (per-object order computation) so they stay in sync.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Sprite Sorting Config")]
public class SpriteSortingConfigSO : ScriptableObject
{
    [Tooltip(
        "World-space axis along which depth is measured — positive = further away.\n\n" +
        "Leave as (0,0,0) to let SpriteSortingManager derive it from the camera's\n" +
        "forward vector at runtime (recommended).\n\n" +
        "Manual examples:\n" +
        "  Pure Z top-down  : (0, 0, 1)\n" +
        "  45° tilted camera: (0, 0.71, 0.71)\n" +
        "  60° tilted camera: (0, 0.87, 0.50)")]
    [SerializeField] private Vector3 _sortAxis = Vector3.zero;

    [Tooltip("Number of sorting-order integers per world unit of depth.\n" +
             "100 → 0.01 wu resolution (good for a 100-tile map).")]
    [Min(1f)]
    public float stepsPerUnit = 100f;

    [Tooltip("Constant added to every computed order.  Increase if you need " +
             "sprite layers to sit above other non-sprite renderers in the scene.")]
    public int baseOrder = 0;

    // ── Runtime ──────────────────────────────────────────────────────────────

    /// <summary>
    /// The normalised sort axis used at runtime.
    /// If _sortAxis is zero, falls back to Camera.main.transform.forward.
    /// SortableSprite and SpriteSortingManager both read this.
    /// </summary>
    public Vector3 SortAxisNormalized
    {
        get
        {
            if (_sortAxis.sqrMagnitude > 0.001f)
                return _sortAxis.normalized;

            // Auto-derive from camera
            if (Camera.main != null)
                return Camera.main.transform.forward;

            return Vector3.forward; // safe fallback
        }
    }

    /// <summary>Allows SpriteSortingManager to push the camera-derived axis back in.</summary>
    public void SetDerivedAxis(Vector3 axis)
    {
        if (_sortAxis.sqrMagnitude < 0.001f)
            return; // only override when axis is set to "auto"
        // No-op when the designer has set an explicit axis.
    }
}

using UnityEngine;
using UnityEngine.Rendering;

/// <summary>
/// Drop this on any scene GameObject (e.g. a "SpriteSortingManager" empty GO).
///
/// What it does
/// ────────────
/// 1. Configures Camera.main's transparency sort mode to CustomAxis so Unity's
///    renderer natively sorts all transparent draw calls (sprites, particles) by
///    their projection onto the sort axis — zero per-frame C# cost.
///
/// 2. Exposes the same SpriteSortingConfigSO used by SortableSprite so both
///    mechanisms always use the same axis and are never out of sync.
///
/// When to add SortableSprite as well
/// ────────────────────────────────────
/// Camera sort mode handles objects on the same sorting layer+order perfectly.
/// Add SortableSprite to any prefab (character, tree, NPC) where you need
/// explicit integer sortingOrder control across heterogeneous objects.
/// </summary>
public class SpriteSortingManager : MonoBehaviour
{
    [SerializeField] private SpriteSortingConfigSO _config;

    [Tooltip("When enabled the manager re-applies the camera sort axis every frame.\n" +
             "Only needed if the camera rotates during play. Leave off for a fixed camera.")]
    [SerializeField] private bool _updateEachFrame = false;

    private Camera _cam;

    private void Awake()
    {
        _cam = Camera.main;
        Apply();
    }

    private void LateUpdate()
    {
        if (_updateEachFrame)
            Apply();
    }

    private void Apply()
    {
        if (_config == null || _cam == null) return;

        Vector3 axis = _config.SortAxisNormalized;

        // Unity-native: sorts all transparent renderers on the same layer by depth.
        _cam.transparencySortMode = TransparencySortMode.CustomAxis;
        _cam.transparencySortAxis = axis;
    }

#if UNITY_EDITOR
    private void OnValidate()
    {
        // Refresh in Edit mode so the Gizmo reflects current settings immediately.
        _cam = Camera.main;
        if (_config != null && _cam != null)
            Apply();
    }

    private void OnDrawGizmosSelected()
    {
        if (_config == null) return;

        Vector3 axis = _config.SortAxisNormalized;
        Vector3 origin = transform.position + Vector3.up * 0.5f;

        Gizmos.color = new Color(0.3f, 0.8f, 1f, 0.9f);
        Gizmos.DrawRay(origin, axis * 3f);

        // Draw a small disc perpendicular to axis (shows the "ground plane" of depth)
        Vector3 perp = Vector3.Cross(axis, Vector3.up);
        if (perp.sqrMagnitude < 0.001f) perp = Vector3.right;
        perp.Normalize();
        Gizmos.color = new Color(0.3f, 0.8f, 1f, 0.3f);
        for (int i = 0; i < 16; i++)
        {
            float a0 = i * Mathf.PI * 2f / 16f;
            float a1 = (i + 1) * Mathf.PI * 2f / 16f;
            Vector3 v0 = origin + Quaternion.AngleAxis(a0 * Mathf.Rad2Deg, axis) * perp;
            Vector3 v1 = origin + Quaternion.AngleAxis(a1 * Mathf.Rad2Deg, axis) * perp;
            Gizmos.DrawLine(v0, v1);
        }
    }
#endif
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Central manager that drives billboard rotation for all registered
/// IBillboardTarget objects from a single LateUpdate loop.
///
/// Replace per-object Billboard.cs Update overhead with a single pass.
/// Existing Billboard.cs components continue working independently for
/// backward compatibility.
/// </summary>
[DefaultExecutionOrder(-100)]
public class BillboardManager : MonoBehaviour
{
    private readonly List<IBillboardTarget> _targets = new();
    private Camera _mainCamera;
    private bool _cameraCached;

    /// <summary>Register a target to receive automatic billboarding.</summary>
    public void Register(IBillboardTarget target)
    {
        if (target == null) return;
        if (!_targets.Contains(target))
            _targets.Add(target);
    }

    /// <summary>Unregister a target so it no longer receives billboarding.</summary>
    public void Unregister(IBillboardTarget target)
    {
        if (target == null) return;
        _targets.Remove(target);
    }

    private void CacheCamera()
    {
        if (!_cameraCached)
        {
            _mainCamera = Camera.main;
            _cameraCached = true;
        }
    }

    private void LateUpdate()
    {
        CacheCamera();
        if (_mainCamera == null) return;

        Vector3 cameraPos = _mainCamera.transform.position;

        for (int i = _targets.Count - 1; i >= 0; i--)
        {
            IBillboardTarget target = _targets[i];
            if (target?.BillboardTransform == null)
            {
                _targets.RemoveAt(i);
                continue;
            }

            Transform t = target.BillboardTransform;
            Vector3 dirToCamera = cameraPos - t.position;

            switch (target.Mode)
            {
                case BillboardMode.Full:
                    t.rotation = Quaternion.LookRotation(dirToCamera);
                    break;

                case BillboardMode.YOnly:
                    Vector3 flatDir = new Vector3(dirToCamera.x, 0f, dirToCamera.z);
                    if (flatDir.sqrMagnitude > 0.001f)
                        t.rotation = Quaternion.LookRotation(flatDir);
                    break;

                case BillboardMode.PitchOnly:
                    float horizontalDist = new Vector2(dirToCamera.x, dirToCamera.z).magnitude;
                    float pitchAngle = Mathf.Atan2(dirToCamera.y, horizontalDist) * Mathf.Rad2Deg;
                    t.rotation = Quaternion.Euler(pitchAngle, t.eulerAngles.y, 0f);
                    break;
            }
        }
    }
}

